public double integrate(final int maxEval, final UnivariateRealFunction f,
                            final double min, final double max)
        throws TooManyEvaluationsException, ConvergenceException,
               MathIllegalArgumentException, NullArgumentException {

        // Initialization.
        setup(maxEval, f, min, max);

        // Perform computation.
        return doIntegrate();

    }

@Override
    protected double doSolve() {
        double min = getMin();
        double max = getMax();
        verifyInterval(min, max);
        final double absoluteAccuracy = getAbsoluteAccuracy();
        double m;
        double fm;
        double fmin;

        while (true) {
            m = UnivariateRealSolverUtils.midpoint(min, max);
            fmin = computeObjectiveValue(min);
            fm = computeObjectiveValue(m);

            if (fm * fmin > 0) {
                // max and m bracket the root.
                min = m;
            } else {
                // min and m bracket the root.
                max = m;
            }

            if (FastMath.abs(max - min) <= absoluteAccuracy) {
                m = UnivariateRealSolverUtils.midpoint(min, max);
                return m;
            }
        }
    }

